import { Component, DestroyRef, ElementRef, ViewChild, computed, inject, signal } from '@angular/core';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { Subscription, finalize } from 'rxjs';
import { errorMessage } from '../core/http-error';
import {
  BulkAction,
  Filters,
  RecordInput,
  RecordItem,
  RecordPage,
  RecordsService,
  Selection,
  Status,
  emptyFilters,
} from '../core/records-service';

type EditorMode = 'create' | 'edit' | 'view';

@Component({
  standalone: true,
  imports: [FormsModule, DatePipe],
  templateUrl: './records.html',
})
export class RecordsPage {
  private readonly api = inject(RecordsService);
  private readonly destroyRef = inject(DestroyRef);
  private request?: Subscription;

  @ViewChild('editor', { static: true }) editor!: ElementRef<HTMLDialogElement>;

  readonly statusLabels: Record<Status, string> = {
    pending: 'Pendiente',
    active: 'Activo',
    archived: 'Archivado',
  };

  readonly actionLabels: Record<BulkAction, string> = {
    activate: 'Marcar como activos',
    pending: 'Marcar como pendientes',
    archive: 'Archivar',
    delete: 'Eliminar',
  };

  readonly bulkActions = Object.keys(this.actionLabels) as BulkAction[];

  // Estado de la página
  readonly result = signal<RecordPage | null>(null);
  readonly loading = signal(false);
  readonly saving = signal(false);
  readonly error = signal('');
  readonly notice = signal('');

  // Filtros y paginación
  filters: Filters = emptyFilters();
  applied: Filters = emptyFilters();
  page = 1;
  perPage = 10;

  // Selección: manual (selected) o todos los resultados menos los excluidos (excluded)
  readonly allSelected = signal(false);
  readonly selected = signal(new Set<number>());
  readonly excluded = signal(new Set<number>());
  bulkAction: BulkAction = 'activate';

  // Formulario del modal
  mode: EditorMode = 'create';
  current: RecordItem | null = null;
  input: RecordInput = this.blankInput();
  readonly formError = signal('');

  readonly rows = computed(() => this.result()?.data ?? []);
  readonly total = computed(() => this.result()?.meta.total ?? 0);
  readonly currentPage = computed(() => this.result()?.meta.page ?? 1);
  readonly lastPage = computed(() => this.result()?.meta.lastPage ?? 1);

  readonly selectionCount = computed(() =>
    this.allSelected() ? this.total() - this.excluded().size : this.selected().size,
  );

  readonly pageSelected = computed(
    () => this.rows().length > 0 && this.rows().every((row) => this.isSelected(row.id)),
  );

  readonly pagePartial = computed(
    () => !this.pageSelected() && this.rows().some((row) => this.isSelected(row.id)),
  );

  constructor() {
    this.destroyRef.onDestroy(() => this.request?.unsubscribe());
    this.load();
  }

  get busy(): boolean {
    return this.loading() || this.saving();
  }

  // ---------- Listado ----------

  load(): void {
    this.request?.unsubscribe();
    this.loading.set(true);
    this.error.set('');

    this.request = this.api.list(this.applied, this.page, this.perPage).subscribe({
      next: (result) => {
        // Si la página quedó vacía (por ejemplo, tras eliminar), vuelve a la última.
        if (this.page > result.meta.lastPage) {
          this.page = result.meta.lastPage;
          this.load();
          return;
        }

        this.result.set(result);
        this.loading.set(false);
      },
      error: (error) => {
        this.error.set(errorMessage(error));
        this.result.set(null);
        this.loading.set(false);
      },
    });
  }

  applyFilters(): void {
    if (this.filters.from && this.filters.to && this.filters.from > this.filters.to) {
      this.error.set('La fecha inicial debe ser anterior a la fecha final.');
      return;
    }

    this.applied = { ...this.filters };
    this.page = 1;
    this.clearSelection();
    this.load();
  }

  resetFilters(): void {
    this.filters = emptyFilters();
    this.applyFilters();
  }

  changePage(page: number): void {
    this.page = page;
    this.load();
  }

  changePerPage(): void {
    this.page = 1;
    this.load();
  }

  // ---------- Selección ----------

  isSelected(id: number): boolean {
    return this.allSelected() ? !this.excluded().has(id) : this.selected().has(id);
  }

  toggle(id: number): void {
    // En modo "todos", desmarcar significa excluir.
    const target = this.allSelected() ? this.excluded : this.selected;
    const ids = new Set(target());

    if (ids.has(id)) {
      ids.delete(id);
    } else {
      ids.add(id);
    }

    target.set(ids);
  }

  togglePage(): void {
    const check = !this.pageSelected();

    for (const row of this.rows()) {
      if (this.isSelected(row.id) !== check) {
        this.toggle(row.id);
      }
    }
  }

  selectAll(): void {
    this.allSelected.set(true);
    this.selected.set(new Set());
    this.excluded.set(new Set());
  }

  clearSelection(): void {
    this.allSelected.set(false);
    this.selected.set(new Set());
    this.excluded.set(new Set());
  }

  // ---------- Acción masiva ----------

  runBulk(): void {
    const count = this.selectionCount();

    if (this.busy || count === 0) {
      return;
    }

    const warning = this.bulkAction === 'delete' ? ' Esta acción no se puede deshacer.' : '';
    const label = this.actionLabels[this.bulkAction].toLowerCase();

    if (!window.confirm(`¿${label} ${count} registro(s)?${warning}`)) {
      return;
    }

    const selection: Selection = this.allSelected()
      ? { all: true, exceptIds: [...this.excluded()] }
      : { all: false, ids: [...this.selected()] };

    this.saving.set(true);
    this.error.set('');

    this.api
      .bulk(this.bulkAction, selection, this.applied)
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        finalize(() => this.saving.set(false)),
      )
      .subscribe({
        next: (response) => {
          this.notice.set(`Acción completada: ${response.affected} registro(s) afectados.`);
          this.clearSelection();
          this.load();
        },
        error: (error) => this.error.set(errorMessage(error)),
      });
  }

  // ---------- CRUD ----------

  open(mode: EditorMode, record: RecordItem | null = null): void {
    this.mode = mode;
    this.current = record;
    this.formError.set('');
    this.input = record
      ? { title: record.title, description: record.description ?? '', status: record.status }
      : this.blankInput();

    this.editor.nativeElement.showModal();
  }

  close(): void {
    if (!this.saving()) {
      this.editor.nativeElement.close();
    }
  }

  onCancel(event: Event): void {
    // Evita cerrar el modal con Escape mientras se guarda.
    if (this.saving()) {
      event.preventDefault();
    }
  }

  save(): void {
    if (this.saving() || this.mode === 'view' || !this.input.title.trim()) {
      return;
    }

    const input = { ...this.input, title: this.input.title.trim() };
    const request = this.current
      ? this.api.update(this.current.id, input)
      : this.api.create(input);

    this.saving.set(true);
    this.formError.set('');

    request
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        finalize(() => this.saving.set(false)),
      )
      .subscribe({
        next: () => {
          this.editor.nativeElement.close();
          this.notice.set(this.current ? 'Registro actualizado.' : 'Registro creado.');
          this.load();
        },
        error: (error) => this.formError.set(errorMessage(error)),
      });
  }

  remove(record: RecordItem): void {
    if (this.busy || !window.confirm(`¿Eliminar “${record.title}”? Esta acción no se puede deshacer.`)) {
      return;
    }

    this.saving.set(true);
    this.error.set('');

    this.api
      .remove(record.id)
      .pipe(
        takeUntilDestroyed(this.destroyRef),
        finalize(() => this.saving.set(false)),
      )
      .subscribe({
        next: () => {
          this.notice.set('Registro eliminado.');
          this.clearSelection();
          this.load();
        },
        error: (error) => this.error.set(errorMessage(error)),
      });
  }

  private blankInput(): RecordInput {
    return { title: '', description: '', status: 'pending' };
  }
}
<!-- Encabezado -->
<div class="page-heading">
  <div>
    <div class="eyebrow">GESTIÓN</div>
    <h1>Registros <span class="count-pill">{{ total() }}</span></h1>
    <p class="muted">Crea, filtra y actualiza tus registros.</p>
  </div>
  <button class="primary" type="button" (click)="open('create')" [disabled]="busy">
    + Nuevo registro
  </button>
</div>

<!-- Resumen -->
<section class="overview" aria-label="Resumen">
  <div>
    <span class="overview-icon" aria-hidden="true">▦</span>
    <div>
      <small>Total de resultados</small>
      <strong>{{ total() }}</strong>
    </div>
  </div>
  <div>
    <span class="overview-icon" aria-hidden="true">☑</span>
    <div>
      <small>Seleccionados</small>
      <strong>{{ selectionCount() }}</strong>
    </div>
  </div>
  <div>
    <span class="overview-icon" aria-hidden="true">⇆</span>
    <div>
      <small>Página</small>
      <strong>{{ currentPage() }} <span>de {{ lastPage() }}</span></strong>
    </div>
  </div>
</section>

<!-- Mensajes -->
@if (notice()) {
  <p class="alert success" role="status">
    {{ notice() }}
    <button class="text-button" type="button" (click)="notice.set('')" aria-label="Cerrar aviso">✕</button>
  </p>
}
@if (error()) {
  <p class="alert error" role="alert">{{ error() }}</p>
}

<section class="records-panel">
  <!-- Filtros -->
  <form class="filters" (ngSubmit)="applyFilters()">
    <div class="search-field">
      <label for="q">Buscar</label>
      <input id="q" name="q" type="search" [(ngModel)]="filters.q" placeholder="Título o descripción">
    </div>
    <div>
      <label for="status">Estado</label>
      <select id="status" name="status" [(ngModel)]="filters.status">
        <option value="">Todos</option>
        <option value="pending">Pendiente</option>
        <option value="active">Activo</option>
        <option value="archived">Archivado</option>
      </select>
    </div>
    <div>
      <label for="from">Desde</label>
      <input id="from" name="from" type="date" [(ngModel)]="filters.from">
    </div>
    <div>
      <label for="to">Hasta</label>
      <input id="to" name="to" type="date" [(ngModel)]="filters.to">
    </div>
    <button class="primary clear-filter" type="submit" [disabled]="busy">Filtrar</button>
    <button class="secondary clear-filter" type="button" (click)="resetFilters()" [disabled]="busy">
      Limpiar
    </button>
  </form>

  <div class="list-heading">
    <div>
      <strong>Listado de registros</strong>
      <span class="muted">Marca filas para aplicar una acción masiva.</span>
    </div>
    @if (result()?.meta; as meta) {
      <span class="list-count">{{ meta.from ?? 0 }}–{{ meta.to ?? 0 }} de {{ meta.total }}</span>
    }
  </div>

  <!-- Acciones masivas -->
  @if (selectionCount() > 0) {
    <div class="bulk-toolbar" role="region" aria-label="Acciones masivas">
      <strong>{{ selectionCount() }} seleccionado(s)</strong>

      @if (allSelected()) {
        <span>Todos los resultados del filtro están seleccionados.</span>
      } @else if (pageSelected() && total() > rows().length) {
        <button class="text-button" type="button" (click)="selectAll()">
          Seleccionar los {{ total() }} resultados
        </button>
      }

      <button class="text-button" type="button" (click)="clearSelection()">Quitar selección</button>

      <div class="bulk-action">
        <select name="bulkAction" aria-label="Acción masiva" [(ngModel)]="bulkAction">
          @for (action of bulkActions; track action) {
            <option [value]="action">{{ actionLabels[action] }}</option>
          }
        </select>
        <button class="primary small" type="button" (click)="runBulk()" [disabled]="busy">
          Aplicar
        </button>
      </div>
    </div>
  }

  <!-- Tabla -->
  <div class="table-scroll">
    <table>
      <thead>
        <tr>
          <th class="checkbox-cell">
            <input
              type="checkbox"
              aria-label="Seleccionar página"
              [checked]="pageSelected()"
              [indeterminate]="pagePartial()"
              [disabled]="busy || rows().length === 0"
              (change)="togglePage()"
            >
          </th>
          <th>TÍTULO</th>
          <th>ESTADO</th>
          <th>CREADO</th>
          <th class="actions-heading">ACCIONES</th>
        </tr>
      </thead>
      <tbody>
        @for (record of rows(); track record.id) {
          <tr [class.selected-row]="isSelected(record.id)">
            <td class="checkbox-cell">
              <input
                type="checkbox"
                [attr.aria-label]="'Seleccionar ' + record.title"
                [checked]="isSelected(record.id)"
                [disabled]="busy"
                (change)="toggle(record.id)"
              >
            </td>
            <td data-label="Título">
              <div class="record-title">
                <span class="file-icon" aria-hidden="true">▤</span>
                <div>
                  <button class="title-button" type="button" (click)="open('view', record)">
                    {{ record.title }}
                  </button>
                  <span class="record-description">{{ record.description || 'Sin descripción' }}</span>
                </div>
              </div>
            </td>
            <td data-label="Estado">
              <span class="badge {{ record.status }}">
                <span></span>{{ statusLabels[record.status] }}
              </span>
            </td>
            <td class="date-cell" data-label="Creado">
              {{ record.createdAt | date: 'dd/MM/yyyy' }}
              <small>{{ record.createdAt | date: 'HH:mm' }}</small>
            </td>
            <td data-label="Acciones">
              <div class="row-actions">
                <button class="text-button" type="button" (click)="open('edit', record)" [disabled]="busy">
                  Editar
                </button>
                <button class="text-button danger" type="button" (click)="remove(record)" [disabled]="busy">
                  Eliminar
                </button>
              </div>
            </td>
          </tr>
        }
      </tbody>
    </table>

    @if (loading()) {
      <div class="empty-state">
        <div class="spinner"></div>
        Cargando registros…
      </div>
    } @else if (rows().length === 0) {
      <div class="empty-state">
        <span class="empty-icon" aria-hidden="true">▢</span>
        <strong>No hay registros</strong>
        Prueba con otros filtros o crea un registro nuevo.
      </div>
    }
  </div>

  <!-- Paginación -->
  @if (result()?.meta; as meta) {
    <nav class="pagination" aria-label="Paginación">
      <div>
        <label for="perPage">Por página</label>
        <select id="perPage" name="perPage" [(ngModel)]="perPage" (ngModelChange)="changePerPage()">
          <option [ngValue]="10">10</option>
          <option [ngValue]="25">25</option>
          <option [ngValue]="50">50</option>
        </select>
      </div>
      <div>
        <button
          class="secondary small"
          type="button"
          (click)="changePage(meta.page - 1)"
          [disabled]="busy || meta.page <= 1"
        >
          Anterior
        </button>
        <span class="page-number">{{ meta.page }}</span>
        <button
          class="secondary small"
          type="button"
          (click)="changePage(meta.page + 1)"
          [disabled]="busy || meta.page >= meta.lastPage"
        >
          Siguiente
        </button>
      </div>
    </nav>
  }
</section>

<!-- Modal: crear, editar y ver -->
<dialog #editor (cancel)="onCancel($event)" aria-labelledby="editorTitle">
  <form (ngSubmit)="save()" #recordForm="ngForm">
    <div class="modal-heading">
      <h2 id="editorTitle">
        @switch (mode) {
          @case ('create') { Nuevo registro }
          @case ('edit') { Editar registro }
          @default { Detalle del registro }
        }
      </h2>
      <button class="text-button" type="button" (click)="close()" aria-label="Cerrar">×</button>
    </div>

    <label for="title">Título</label>
    <input
      id="title"
      name="title"
      [(ngModel)]="input.title"
      required
      maxlength="255"
      [readonly]="mode === 'view'"
    >

    <label for="description">Descripción</label>
    <textarea
      id="description"
      name="description"
      [(ngModel)]="input.description"
      maxlength="10000"
      [readonly]="mode === 'view'"
    ></textarea>

    <label for="recordStatus">Estado</label>
    <select id="recordStatus" name="status" [(ngModel)]="input.status" [disabled]="mode === 'view'">
      <option value="pending">Pendiente</option>
      <option value="active">Activo</option>
      <option value="archived">Archivado</option>
    </select>

    @if (formError()) {
      <p class="alert error" role="alert">{{ formError() }}</p>
    }

    <div class="modal-footer">
      <button class="secondary" type="button" (click)="close()" [disabled]="saving()">
        {{ mode === 'view' ? 'Cerrar' : 'Cancelar' }}
      </button>
      @if (mode !== 'view') {
        <button class="primary" type="submit" [disabled]="recordForm.invalid || saving()">
          {{ saving() ? 'Guardando…' : 'Guardar' }}
        </button>
      }
    </div>
  </form>
</dialog>
